'use strict';
const roundConfig=window.PREP_CONTENT.rounds;
const roleConfig=window.PREP_CONTENT.roles;
const roundFor=id=>roundConfig.find(r=>r.id===id)||roundConfig[0];
const roleName=()=>roleConfig.find(r=>r.id===currentRole)?.name||'All roles';
const pathSummary=()=>`${currentDomain} · ${languageConfig[currentLanguage].name} · ${roleName()}`;
const forRound=(items,id)=>{const result=scoped(items).filter(i=>i.rounds?.includes(id)&&i.category!=='Parsing archive');return id==='coding'?result.sort((a,b)=>Number(b.programming)-Number(a.programming)):result;};
function roundCards(){return `<div class="round-grid">${roundConfig.map((r,n)=>`<a class="round-card" href="#/round/${r.id}"><span class="round-number">0${n+1}<span>↗</span></span><span class="round-tag">${r.label}</span><h3>${r.name}</h3><p>${r.description}</p><span class="round-card-bottom">Explore round <span>→</span></span></a>`).join('')}</div>`;}
function publicHome(){return `<section class="public-hero"><div class="hero-message"><span class="public-eyebrow"><i></i> INTERVIEW PREPARATION, ROUND BY ROUND</span><h1>Prepare for the interview.<br><em>Every round of it.</em></h1><p>From a confident introduction to a thoughtful technical answer. Build the knowledge, practise the conversation and get ready for the role you want.</p><div class="hero-actions"><a class="button primary large" href="#/rounds">Explore interview rounds <span>→</span></a><a class="button large" href="#/lab?round=coding">Try the practice lab <span>↗</span></a></div><div class="hero-trust"><span>6 domains</span><i></i><span>4 programming languages</span><i></i><span>7 role paths</span></div></div><aside class="preview-interview"><div class="preview-label"><span class="live-dot"></span> A LOOK INSIDE PREPSPACE <span>01 / 05</span></div><div class="preview-question"><span class="pill">Introduction Round</span><h2>“Tell me about yourself.”</h2><p>A familiar question. A more focused answer.</p></div><div class="answer-outline"><span>BUILD YOUR ANSWER</span><div><b>01</b><p><strong>Where you are now</strong><small>Your current focus and relevant strengths.</small></p></div><div><b>02</b><p><strong>What you have contributed</strong><small>A real example and a verifiable result.</small></p></div><div><b>03</b><p><strong>Where you want to go</strong><small>Connect your experience to this role.</small></p></div></div><a href="#/lab?round=introduction&question=intro-about-yourself" class="preview-action">Practise this question <span>→</span></a></aside></section><section class="explore-entry"><div class="section-intro"><span class="public-eyebrow">FIND A STARTING POINT</span><h2>Different careers. A path that fits.</h2><p>Start with the industry you know, the language you write or the role you’re working toward.</p></div><div class="entry-grid"><a href="#/domains" class="entry-card"><span class="entry-icon">◈</span><h3>Prepare by domain</h3><p>Banking, commerce, AI, cloud and data. Work through scenarios grounded in a business context.</p><span>Explore 6 domains →</span></a><a href="#/languages" class="entry-card"><span class="entry-icon mono">{ }</span><h3>Prepare by language</h3><p>Study concepts and practise coding in Java, Python, JavaScript or TypeScript.</p><span>Choose a language →</span></a><a href="#/roles" class="entry-card"><span class="entry-icon">◎</span><h3>Prepare by role</h3><p>Focus on the decisions and skills expected of engineers, test leaders and technical managers.</p><span>Browse role paths →</span></a></div></section><section class="round-section"><div class="section-intro"><span class="public-eyebrow">THE COMPLETE INTERVIEW JOURNEY</span><h2>Five rounds. One clear preparation path.</h2><p>Move from general questions to live coding, technical depth, stakeholder conversations and mutual fit. Adapt the sequence to your interview format.</p></div>${roundCards()}</section><section class="learning-system"><div><span class="public-eyebrow">MORE THAN A QUESTION BANK</span><h2>Understand it.<br>Explain it.<br><em>Practise it.</em></h2><p>Every round brings together the material and the practice needed to turn a familiar topic into a clear answer.</p><a class="text-link" href="#/round/introduction">See how a round works ↗</a></div><ol class="learning-steps"><li><span>01</span><div><h3>Concepts & methods</h3><p>Learn the idea, the mechanism and when to use it.</p></div></li><li><span>02</span><div><h3>Questions & scenarios</h3><p>Explore realistic prompts and the assumptions to clarify.</p></div></li><li><span>03</span><div><h3>Prospective answers</h3><p>Compare a worked solution or an illustrative answer structure.</p></div></li><li><span>04</span><div><h3>Practice lab</h3><p>Write code or rehearse an answer in a focused session.</p></div></li><li><span>05</span><div><h3>Best practices</h3><p>Review the answer against useful checks and refine it.</p></div></li></ol></section><section class="bottom-cta"><div><h2>Make the next conversation count.</h2><p>Choose a path. Pick a round. Start with one question.</p></div><a class="button primary large" href="#/rounds">Start preparing →</a></section>`;}
function roundIndex(){return heading('Prepare for every interview round.','Choose a round, then explore its concepts, questions, prospective answers and practice lab.')+`<div class="path-context"><span>PREPARATION PATH</span><strong>${esc(pathSummary())}</strong><small>Use the filters above to change the focus.</small></div>${currentRole!=='all'?roleBrief():''}${roundCards()}<div class="domain-note">Interview formats vary. Use this sequence as a preparation framework and follow the format your recruiter or interviewer confirms.</div>`;}
function roleBrief(){const role=roleConfig.find(r=>r.id===currentRole);return role?`<section class="role-brief"><span class="public-eyebrow">ROLE FOCUS · ${esc(role.name)}</span><ul>${role.focus.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:'';}
function itemCards(items,type){if(!items.length)return `<div class="empty"><h2>No exact matches for this path.</h2><p>Choose another domain or role, or browse the common preparation material.</p><a class="button" href="#/rounds?role=all&domain=All%20domains">Browse all paths →</a></div>`;return `<div class="lesson-grid">${items.map(i=>`<article class="lesson-card"><span class="pill">${i.domain==='Shared'?'Common preparation':esc(i.domain)}</span>${i.programming?`<span class="domain-pill">${languageConfig[i.language].name}</span>`:''}<h3>${esc(i.title)}</h3><p>${type==='concept'?'Concepts, techniques and a scenario to work through.':i.solved?'Includes an answer approach, explanation and follow-up questions.':'Independent practice prompt with related concept material.'}</p><div class="lesson-card-bottom">${lessonLink(i,type==='concept'?'Explore concept':'Open question')}${type!=='concept'?`<a class="button quiet small" href="#/lab?round=${route().path.startsWith('round/')?route().path.split('/')[1]:i.rounds?.[0]||'technical'}&question=${i.id}">Practise ↗</a>`:''}${saveButton(i)}</div></article>`).join('')}</div>`;}
function roundPage(){const r=route(),round=roundFor(r.path.split('/')[1]),tab=['concepts','questions','lab','best'].includes(r.query.get('tab'))?r.query.get('tab'):'concepts';const lessons=forRound(concepts,round.id),questions=forRound(problems,round.id);const content=tab==='concepts'?`<div class="section-head"><h2>Build the concepts</h2><span class="muted">${lessons.length} resources</span></div>${itemCards(lessons,'concept')}`:tab==='questions'?`<div class="section-head"><h2>Questions & prospective answers</h2><span class="muted">${questions.length} questions</span></div>${itemCards(questions,'problem')}`:tab==='best'?bestPracticeBlock(round):`<section class="lab-intro"><span class="public-eyebrow">PRACTISE WITH INTENTION</span><h2>${round.outcome}</h2><p>Pick a question, outline or code your answer, use the timer and compare against the sample answer. Notes stay in this browser.</p><a class="button primary" href="#/lab?round=${round.id}">Open ${round.short.toLowerCase()} practice lab →</a><ul>${round.rubric.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`;return `<a class="back-link" href="#/rounds">← All interview rounds</a><section class="round-page-heading"><div><span class="public-eyebrow">ROUND ${roundConfig.indexOf(round)+1} OF 5 · ${round.label}</span><h1>${round.name}</h1><p>${round.description}</p><span class="path-caption">${esc(pathSummary())}</span></div><a class="button primary" href="#/lab?round=${round.id}">Start practising ↗</a></section>${currentRole!=='all'?roleBrief():''}<nav class="round-tabs" aria-label="Resources for this interview round">${[['concepts','Concepts & methods'],['questions','Questions & answers'],['lab','Practice lab'],['best','Best practices']].map(([id,name])=>`<a href="#/round/${round.id}?tab=${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${name}</a>`).join('')}</nav><section class="round-content">${content}</section>`;}
function bestPracticeBlock(round){return `<div class="best-practice-layout"><section><h2>Best practices for the ${round.short.toLowerCase()} round</h2><ol class="best-list">${round.best.map((x,n)=>`<li><span>0${n+1}</span><p>${esc(x)}</p></li>`).join('')}</ol></section><aside class="self-review-card"><span class="public-eyebrow">AFTER YOUR ANSWER</span><h3>Use these self-checks</h3><ul>${round.rubric.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><a class="button" href="#/lab?round=${round.id}">Put it into practice →</a></aside></div>`;}
function bestPracticesPage(){return heading('Best practices for every round.','Use a clear structure, test your assumptions and refine the answer after each attempt.')+roundConfig.map(r=>`<section class="best-round"><span class="pill">${r.name}</span>${bestPracticeBlock(r)}</section>`).join('');}
function domainsPage(){return heading('Prepare by domain.','Build context for the workflows, failure modes and decisions discussed in your interview.')+`<div class="domain-catalog">${domains.map((d,n)=>`<article class="catalog-card"><span class="catalog-number">0${n+1} / ${['IB','CB','EC','AI','CL','DE'][n]}</span><h2>${d}</h2><p>${domainDescriptions[d]}</p><div class="catalog-topics">${concepts.filter(i=>i.domain===d).slice(0,2).map(i=>`<span>${esc(i.title)}</span>`).join('')}</div><a class="button primary" href="#/rounds?domain=${encodeURIComponent(d)}&role=all&category=All">Prepare for ${d} →</a></article>`).join('')}</div>`;}
function languagesPage(){return heading('Prepare in the language you use.','Study the actual object, collection, arithmetic and concurrency semantics of your chosen language.')+`<div class="language-catalog">${Object.entries(languageConfig).map(([id,c],n)=>`<article class="catalog-card"><span class="language-badge">${['J','Py','JS','TS'][n]}</span><h2>${c.name}</h2><p>${{java:'Object design, collections, Streams, BigDecimal and executor-based concurrency.',python:'Dataclasses, dictionaries, comprehensions, Decimal, futures and asyncio.',javascript:'Objects, Map and Set, array pipelines, exact integer money and promises.',typescript:'Typed contracts with JavaScript runtime semantics, collections, exact arithmetic and async work.'}[id]}</p><a class="button primary" href="#/round/coding?language=${id}&domain=All%20domains&role=all&tab=concepts">Explore ${c.name} preparation →</a></article>`).join('')}</div><div class="domain-note">Coding answers are available in all four languages for the core exercises. The original archived HTML exercises retain their labelled Java source. The practice lab links to an external compiler; this site does not execute code.</div>`;}
function rolesPage(){return heading('Prepare for the role you want.','Focus your preparation on the responsibilities and decisions that matter for the role.')+`<div class="role-catalog">${roleConfig.map((r,n)=>`<article class="catalog-card"><span class="catalog-number">ROLE PATH / 0${n+1}</span><h2>${r.name}</h2><p>${r.tag}</p><ul>${r.focus.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><a class="button primary" href="#/rounds?role=${r.id}&domain=All%20domains">Explore this role →</a></article>`).join('')}</div>`;}
function labQuestion(){const r=route(),round=roundFor(r.query.get('round')||'coding');const questions=forRound(problems,round.id);return {round,questions,item:questions.find(i=>i.id===r.query.get('question'))||questions[0]};}
function timerDuration(){return route().path==='lab'?labQuestion().round.minutes*60:1500;}
function labPage(){const {round,questions,item}=labQuestion();if(!item)return heading('Practice lab','Choose a domain or role with a matching practice question.')+`<div class="empty"><h2>No matching questions for this path.</h2><p>Change the filters above or explore all preparation paths.</p><a class="button" href="#/rounds?domain=All%20domains&role=all">Browse all paths →</a></div>`;const coding=item.programming,config=languageConfig[item.language]||languageConfig[currentLanguage],key=draftKey(item),value=state.drafts[key]??(coding&&item.language==='java'?state.drafts[item.id]:undefined)??(coding?starterCode(item.language):'Opening or recommendation:\n\nEvidence and reasoning:\n\nTrade-offs and assumptions:\n\nChecks or next step:\n');const checks=state.assessments?.[key]||[];return heading('Practice lab','Choose a question, build your answer and review it with a clear set of checks.')+`<div class="lab-controls"><div><label for="lab-round">INTERVIEW ROUND</label><select id="lab-round">${roundConfig.map(r=>`<option value="${r.id}" ${r.id===round.id?'selected':''}>${r.name}</option>`).join('')}</select></div><div><label for="lab-question">PRACTICE QUESTION</label><select id="lab-question">${questions.map(i=>`<option value="${i.id}" ${i.id===item.id?'selected':''}>${esc(i.title)}</option>`).join('')}</select></div><div class="timer"><output id="timer-output" class="timer-output" aria-label="Focus time remaining">${timerText()}</output><button class="button primary small" id="timer-toggle">${timerRunning?'Pause':'Start focus'}</button><button class="button small" id="timer-reset">Reset</button></div></div><div class="lab-grid"><section class="lab-work"><div class="lab-prompt reading-body"><span class="pill">${round.name} · ${item.domain==='Shared'?'Common preparation':esc(item.domain)}${coding?' · '+config.name:''}</span><h2>${esc(item.title)}</h2>${item.question}</div><div class="lab-editor"><div class="pad-heading"><h3>${coding?config.name+' solution':'Answer outline'}</h3><span>Saved in this browser</span></div><label class="sr-only" for="lab-answer">Practice lab answer</label><textarea id="lab-answer" class="${coding?'code-editor':'prose-editor'}" spellcheck="${!coding}">${esc(value)}</textarea><div class="pad-actions"><button class="button small" id="copy-lab">Copy answer</button>${coding?`<a class="button primary small" href="${config.compiler}" target="_blank" rel="noopener">Open ${config.name} compiler ↗</a><small>Copy the code there to compile or run it.</small>`:'<small>Use real examples for experience questions. The illustrative answer is a structure to adapt.</small>'}</div></div>${item.solved?`<details class="answer lab-sample"><summary>Compare with a prospective answer${coding?' / worked solution':''}</summary><div class="answer-content reading-body">${item.answer}</div></details>`:'<div class="domain-note">This is an independent practice prompt. Use the related concepts and self-checks to review your approach.</div>'}</section><aside class="lab-checks"><span class="public-eyebrow">REFLECT, THEN REFINE</span><h2>Answer self-check</h2><p>Use the criteria to review your own answer. This is a self-assessment, not an automatic grade.</p>${round.rubric.map((x,n)=>`<label><input type="checkbox" data-assessment="${n}" ${checks.includes(n)?'checked':''}><span>${esc(x)}</span></label>`).join('')}<div id="assessment-status">${checks.length} of ${round.rubric.length} checks reviewed</div><a class="text-link" href="#/round/${round.id}?tab=best">Read round best practices ↗</a></aside></div>`;}
document.addEventListener('change',e=>{if(e.target.id==='role-select'){currentRole=e.target.value;state.role=currentRole;category='All';persist();const r=route();r.query.delete('role');r.query.delete('category');history.replaceState(null,'','#/'+r.path+(r.query.toString()?'?'+r.query.toString():''));render();}if(e.target.id==='lab-round'){timerRunning=false;timerRemaining=roundFor(e.target.value).minutes*60;go('lab?round='+e.target.value);}if(e.target.id==='lab-question'){const round=labQuestion().round;timerRunning=false;timerRemaining=round.minutes*60;go('lab?round='+round.id+'&question='+e.target.value);}if(e.target.matches('[data-assessment]')){const {item,round}=labQuestion(),key=draftKey(item),n=Number(e.target.dataset.assessment);state.assessments=state.assessments||{};const values=state.assessments[key]||[];state.assessments[key]=e.target.checked?[...new Set([...values,n])]:values.filter(x=>x!==n);persist();$('#assessment-status').textContent=state.assessments[key].length+' of '+round.rubric.length+' checks reviewed';}});
document.addEventListener('input',e=>{if(e.target.id==='lab-answer'){const {item}=labQuestion();state.drafts[draftKey(item)]=e.target.value;persist();}});
document.addEventListener('click',async e=>{if(e.target.closest('#copy-lab'))await copyText($('#lab-answer').value,$('#copy-lab'));});
